235	    /// Consume one upstream SSE chunk and produce zero or more [`ModelEvent`]s.
236	    ///
237	    /// Event ordering within a chunk follows the "Usage before Finish" contract
238	    /// stated in [`paigasus_helikon_core::Model::invoke`]:
239	    /// 1. `TokenDelta` / `ToolCallDelta` (generation deltas)
240	    /// 2. `Usage` (when `chunk.usage` is present — final chunk only)
241	    /// 3. `Finish` (terminal; always last)
242	    pub(crate) fn consume(&mut self, chunk: CreateChatCompletionStreamResponse) -> Vec<ModelEvent> {
243	        let mut out: Vec<ModelEvent> = Vec::new();
244	        let mut finish_event: Option<ModelEvent> = None;
245	
246	        for choice in &chunk.choices {
247	            // Text deltas.
248	            if let Some(content) = choice.delta.content.as_deref() {
249	                if !content.is_empty() {
250	                    out.push(ModelEvent::TokenDelta {
251	                        text: content.to_owned(),
252	                    });
253	                }
254	            }
255	
256	            // Tool-call deltas.
257	            if let Some(tcs) = choice.delta.tool_calls.as_ref() {
258	                for tc in tcs {
259	                    self.handle_tool_call_chunk(tc, &mut out);
260	                }
261	            }
262	
263	            // Stash finish reason — emitted last (after Usage) below.
264	            if let Some(reason) = choice.finish_reason {
265	                let mapped = match reason {
266	                    OaFinishReason::Stop => FinishReason::Stop,
267	                    OaFinishReason::Length => FinishReason::Length,
268	                    OaFinishReason::ToolCalls => FinishReason::ToolCalls,
269	                    OaFinishReason::ContentFilter => FinishReason::ContentFilter,
270	                    OaFinishReason::FunctionCall => FinishReason::Other("function_call".to_owned()),
271	                    // OaFinishReason has no #[non_exhaustive] in 0.40 but guard for robustness.
272	                    #[allow(unreachable_patterns)]
273	                    other => FinishReason::Other(format!("{other:?}")),
274	                };
275	                finish_event = Some(ModelEvent::Finish { reason: mapped });
276	            }
277	        }
278	
279	        // Usage arrives on the final chunk (after `include_usage: true`).
280	        // Emitted after generation deltas but BEFORE the Finish event, per
281	        // the ordering contract ("Usage MAY appear anywhere; Finish is terminal").
282	        if let Some(u) = chunk.usage.as_ref() {
283	            out.push(ModelEvent::Usage {
284	                input_tokens: u.prompt_tokens,
285	                output_tokens: u.completion_tokens,
286	                cached_input_tokens: u
287	                    .prompt_tokens_details
288	                    .as_ref()
289	                    .and_then(|d| d.cached_tokens),
290	                reasoning_tokens: u
291	                    .completion_tokens_details
292	                    .as_ref()
293	                    .and_then(|d| d.reasoning_tokens),
294	            });
295	        }
296	
297	        // Append Finish last (terminal event).
298	        if let Some(finish) = finish_event {
299	            out.push(finish);
300	        }
301	
302	        out
303	    }
