7	/// Stateful translator from Gemini SSE chunks to core `ModelEvent`s.
8	pub(crate) struct StreamTranslator {
9	    fn_index: usize,
10	    saw_function_call: bool,
11	    finish_reason: Option<String>,
12	}
13	
14	impl StreamTranslator {
15	    pub(crate) fn new() -> Self {
16	        Self {
17	            fn_index: 0,
18	            saw_function_call: false,
19	            finish_reason: None,
20	        }
21	    }
22	
23	    pub(crate) fn consume(&mut self, chunk: GeminiChunk) -> Vec<Result<ModelEvent, ModelError>> {
24	        let mut out = Vec::new();
25	
26	        if let Some(pf) = &chunk.prompt_feedback {
27	            if let Some(reason) = &pf.block_reason {
28	                out.push(Err(ModelError::Refused {
29	                    reason: format!("prompt blocked: {reason}"),
30	                }));
31	                return out;
32	            }
33	        }
34	
35	        if let Some(cand) = chunk.candidates.into_iter().next() {
36	            if let Some(content) = cand.content {
37	                for part in content.parts {
38	                    if let Some(text) = part.text {
39	                        out.push(Ok(ModelEvent::TokenDelta { text }));
40	                    } else if let Some(fc) = part.function_call {
41	                        self.saw_function_call = true;
42	                        let call_id = fc.id.unwrap_or_else(|| {
43	                            let id = format!("fc_{}", self.fn_index);
44	                            self.fn_index += 1;
45	                            id
46	                        });
47	                        out.push(Ok(ModelEvent::ToolCallDelta {
48	                            call_id,
49	                            name: Some(fc.name),
50	                            args_delta: fc.args.to_string(),
51	                        }));
52	                    }
53	                }
54	            }
55	            if let Some(fr) = cand.finish_reason {
56	                self.finish_reason = Some(fr);
57	            }
58	        }
59	
60	        if let Some(u) = chunk.usage_metadata {
61	            out.push(Ok(ModelEvent::Usage {
62	                input_tokens: u.prompt_token_count,
63	                output_tokens: u.candidates_token_count,
64	                cached_input_tokens: u.cached_content_token_count,
65	                reasoning_tokens: u.thoughts_token_count,
66	            }));
67	        }
68	
69	        out
70	    }
71	
72	    /// Emit the terminal `Finish` — only when a `finishReason` was observed.
73	    pub(crate) fn finish(&mut self) -> Vec<Result<ModelEvent, ModelError>> {
74	        let Some(reason) = self.finish_reason.take() else {
75	            return Vec::new();
76	        };
77	        let fr = match reason.as_str() {
78	            "STOP" if self.saw_function_call => FinishReason::ToolCalls,
79	            "STOP" => FinishReason::Stop,
80	            "MAX_TOKENS" => FinishReason::Length,
81	            "SAFETY" | "RECITATION" | "PROHIBITED_CONTENT" | "BLOCKLIST" | "SPII" => {
82	                FinishReason::ContentFilter
83	            }
84	            other => FinishReason::Other(other.to_owned()),
85	        };
86	        vec![Ok(ModelEvent::Finish { reason: fr })]
87	    }
88	}
