/// SMA-522: cancelling AFTER the finish chunk must still emit no Finish.
/// The core contract requires cancellation to end the stream without one,
/// and the reason is buffered at that point rather than already emitted.
#[tokio::test]
async fn cancellation_after_finish_chunk_emits_no_finish() {
    let server = MockServer::start().await;

    // Finish chunk arrives immediately; the stream then stalls before EOF,
    // so cancellation fires while the finish reason is buffered.
    let body = concat!(
        "data: {\"id\":\"x\",\"object\":\"chat.completion.chunk\",\"created\":1,\"model\":\"gpt-4o\",",
        "\"choices\":[{\"index\":0,\"delta\":{},\"finish_reason\":\"stop\"}]}\n\n",
    );

    Mock::given(method("POST"))
        .and(path("/chat/completions"))
        .respond_with(
            ResponseTemplate::new(200)
                .set_delay(Duration::from_millis(10))
                .set_body_raw(body.as_bytes(), "text/event-stream")
                .set_delay(Duration::from_millis(10)),
        )
        .mount(&server)
        .await;

    let model = OpenAiModel::chat("gpt-4o")
        .api_key("sk-test")
        .base_url(server.uri())
        .build()
        .unwrap();

    let cancel = CancellationToken::new();
    let cancel_clone = cancel.clone();
    tokio::spawn(async move {
        tokio::time::sleep(Duration::from_millis(30)).await;
        cancel_clone.cancel();
    });

    let mut req = ModelRequest::new();
    req.messages = vec![user("hi")];

    if let Ok(mut s) = model.invoke(req, cancel).await {
        let mut emitted = Vec::new();
        while let Some(item) = s.next().await {
            if let Ok(ev) = item {
                emitted.push(ev);
            }
        }
        assert!(
            !emitted
                .iter()
                .any(|e| matches!(e, ModelEvent::Finish { .. })),
            "cancellation must not emit a buffered Finish: {emitted:#?}"
        );
    }
}
```

